namespace CSharpPracticum.Tasks.Level2;
internal class FileWriter(string path):IDisposable{private readonly StreamWriter writer=new(path);public void Write(string text)=>writer.WriteLine(text);public void Dispose()=>writer.Dispose();}
internal class Task31_FileWriter:ITask{public string Title=>"Задание 31: IDisposable + using";public string Description=>"Освобождать StreamWriter через IDisposable и using.";public string[] Requirements=>new[]{"FileWriter содержит StreamWriter и реализует Dispose.","Показать using-блок и using-декларацию."};public void Run(){string path=Path.Combine(Path.GetTempPath(),"task31.txt");using(FileWriter w=new(path))w.Write("Запись через using");using FileWriter w2=new(path);w2.Write("Запись через using var");Console.WriteLine("Обе записи выполнены, файл освобождён при выходе из using.");}}
